// Claude's review tests for A8 (scenario bulk operations). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { clearProject, deleteScenarios, mergeProject, replaceProject, uniqueName } from './scenarioOps';
import type { Mock, Project, SocketMock } from './types';

function mock(id: string, urlPattern = `/${id}`): Mock {
  return {
    id,
    enabled: true,
    method: 'GET',
    urlPattern,
    response: { status: 200, headers: {}, body: id, bodyEncoding: 'text', delayMs: 0 },
    source: 'manual',
    createdAt: 1,
  };
}

function socket(id: string): SocketMock {
  return { id, enabled: true, kind: 'plain', urlPattern: `/ws/${id}`, onConnect: [], replies: [], createdAt: 1 };
}

function target(): Project {
  return {
    id: 'proj',
    name: 'shop.test',
    origins: ['http://shop.test'],
    activeScenarioId: 'b',
    scenarios: [
      { id: 'default', name: 'Default', mocks: [mock('d1'), mock('d2')], sockets: [socket('ds')] },
      { id: 'a', name: 'Server down', mocks: [mock('a1')] },
      { id: 'b', name: 'Slow', mocks: [mock('b1')] },
      { id: 'c', name: 'Empty', mocks: [] },
    ],
  };
}

function incoming(): Project {
  return {
    id: 'other',
    name: 'file',
    origins: ['http://file.test'],
    activeScenarioId: 'x2',
    scenarios: [
      { id: 'x1', name: 'Default', mocks: [mock('i1', '/in/1')], sockets: [socket('is')] },
      { id: 'x2', name: 'Server down', mocks: [mock('i2', '/in/2')] },
      { id: 'x3', name: 'Fresh', mocks: [mock('i3', '/in/3')] },
    ],
  };
}

function counter(): () => string {
  let n = 0;
  return () => `new${++n}`;
}

describe('deleteScenarios', () => {
  it('removes the listed scenarios and keeps the others in order', () => {
    const p = deleteScenarios(target(), ['a', 'c']);
    expect(p.scenarios.map((s) => s.id)).toEqual(['default', 'b']);
    expect(p.activeScenarioId).toBe('b');
  });

  it('never removes the first scenario (Default)', () => {
    const p = deleteScenarios(target(), ['default', 'a']);
    expect(p.scenarios.map((s) => s.id)).toEqual(['default', 'b', 'c']);
    expect(p.scenarios[0]!.mocks.map((m) => m.id)).toEqual(['d1', 'd2']);
  });

  it('moves the active scenario to Default when the active one is deleted', () => {
    const p = deleteScenarios(target(), ['b']);
    expect(p.activeScenarioId).toBe('default');
  });

  it('keeps the project id, name and origins, and does not change its input', () => {
    const t = target();
    const before = JSON.stringify(t);
    const p = deleteScenarios(t, ['a', 'b', 'c']);
    expect(JSON.stringify(t)).toBe(before);
    expect(p).toMatchObject({ id: 'proj', name: 'shop.test', origins: ['http://shop.test'] });
    expect(p.scenarios).toHaveLength(1);
  });

  it('ignores ids it does not know', () => {
    expect(deleteScenarios(target(), ['nope']).scenarios).toHaveLength(4);
  });
});

describe('clearProject', () => {
  it('keeps only Default, emptied, with its id and name, and makes it active', () => {
    const p = clearProject(target());
    expect(p.scenarios).toHaveLength(1);
    expect(p.scenarios[0]).toMatchObject({ id: 'default', name: 'Default', mocks: [] });
    expect(p.scenarios[0]!.sockets ?? []).toEqual([]);
    expect(p.activeScenarioId).toBe('default');
    expect(p).toMatchObject({ id: 'proj', name: 'shop.test', origins: ['http://shop.test'] });
  });

  it('does not change its input', () => {
    const t = target();
    const before = JSON.stringify(t);
    clearProject(t);
    expect(JSON.stringify(t)).toBe(before);
  });
});

describe('uniqueName', () => {
  it('keeps a free name', () => {
    expect(uniqueName('Fresh', ['Default', 'Slow'])).toBe('Fresh');
  });
  it('adds (2), then (3)', () => {
    expect(uniqueName('Slow', ['Default', 'Slow'])).toBe('Slow (2)');
    expect(uniqueName('Slow', ['Slow', 'Slow (2)'])).toBe('Slow (3)');
  });
});

describe('mergeProject (Import: Add to my mocks)', () => {
  it("appends the file's Default mocks and sockets to Default, after the existing ones", () => {
    const p = mergeProject(target(), incoming(), counter());
    const def = p.scenarios[0]!;
    expect(def.id).toBe('default');
    expect(def.mocks.map((m) => m.urlPattern)).toEqual(['/d1', '/d2', '/in/1']);
    expect((def.sockets ?? []).map((s) => s.urlPattern)).toEqual(['/ws/ds', '/ws/is']);
  });

  it('appends the other scenarios, renaming a name that exists', () => {
    const p = mergeProject(target(), incoming(), counter());
    expect(p.scenarios.map((s) => s.name)).toEqual(['Default', 'Server down', 'Slow', 'Empty', 'Server down (2)', 'Fresh']);
    expect(p.scenarios[4]!.mocks.map((m) => m.urlPattern)).toEqual(['/in/2']);
  });

  it('gives every added scenario, mock and socket a new id', () => {
    const p = mergeProject(target(), incoming(), counter());
    const ids = [
      ...p.scenarios.map((s) => s.id),
      ...p.scenarios.flatMap((s) => s.mocks.map((m) => m.id)),
      ...p.scenarios.flatMap((s) => (s.sockets ?? []).map((x) => x.id)),
    ];
    expect(new Set(ids).size).toBe(ids.length);
    for (const old of ['x1', 'x2', 'x3', 'i1', 'i2', 'i3', 'is']) expect(ids).not.toContain(old);
    // The ones that were there keep theirs.
    for (const kept of ['default', 'a', 'b', 'c', 'd1', 'd2', 'ds', 'a1', 'b1']) expect(ids).toContain(kept);
  });

  it('keeps the content of added mocks', () => {
    const p = mergeProject(target(), incoming(), counter());
    const added = p.scenarios[5]!.mocks[0]!;
    expect({ ...added, id: 'x' }).toEqual({ ...mock('i3', '/in/3'), id: 'x' });
  });

  it("keeps the target's id, name, origins and active scenario, and does not change either input", () => {
    const t = target();
    const i = incoming();
    const bt = JSON.stringify(t);
    const bi = JSON.stringify(i);
    const p = mergeProject(t, i, counter());
    expect(p).toMatchObject({ id: 'proj', name: 'shop.test', origins: ['http://shop.test'], activeScenarioId: 'b' });
    expect(JSON.stringify(t)).toBe(bt);
    expect(JSON.stringify(i)).toBe(bi);
  });
});

describe('replaceProject (Import: Replace all)', () => {
  it("takes the file's scenarios and keeps the target's id, name and origins", () => {
    const p = replaceProject(target(), incoming());
    expect(p).toMatchObject({ id: 'proj', name: 'shop.test', origins: ['http://shop.test'] });
    expect(p.scenarios.map((s) => s.name)).toEqual(['Default', 'Server down', 'Fresh']);
    expect(p.scenarios[0]!.mocks.map((m) => m.urlPattern)).toEqual(['/in/1']);
  });

  it("takes the file's active scenario when it exists, else its first", () => {
    expect(replaceProject(target(), incoming()).activeScenarioId).toBe('x2');
    const i = incoming();
    i.activeScenarioId = 'gone';
    expect(replaceProject(target(), i).activeScenarioId).toBe('x1');
  });

  it('a file with no scenarios leaves one empty Default', () => {
    const i = incoming();
    i.scenarios = [];
    const p = replaceProject(target(), i);
    expect(p.scenarios).toHaveLength(1);
    expect(p.scenarios[0]).toMatchObject({ id: 'default', name: 'Default', mocks: [] });
    expect(p.scenarios[0]!.sockets ?? []).toEqual([]);
    expect(p.activeScenarioId).toBe('default');
  });
});
